CREATE TABLE billing_plan_versions(workspace_id uuid NOT NULL,id uuid NOT NULL,plan_key text NOT NULL,version integer NOT NULL,name text NOT NULL,currency text NOT NULL,monthly_amount numeric(24,6) NOT NULL,features jsonb NOT NULL,quotas jsonb NOT NULL,effective_at timestamptz NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,plan_key,version));
CREATE TABLE billing_subscriptions(workspace_id uuid NOT NULL,id uuid NOT NULL,plan_version_id uuid NOT NULL,provider_customer_ref text,provider_subscription_ref text,state text NOT NULL CHECK(state IN('trial','active','past_due','unpaid','paused','canceled','incomplete','grace','enterprise_contract')),period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,cancel_at_period_end boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,plan_version_id) REFERENCES billing_plan_versions(workspace_id,id));
CREATE UNIQUE INDEX billing_subscriptions_current_idx ON billing_subscriptions(workspace_id) WHERE state NOT IN('canceled');
CREATE TABLE billing_webhook_receipts(workspace_id uuid NOT NULL,id uuid NOT NULL,provider_event_id text NOT NULL,event_type text NOT NULL,signature_version text NOT NULL,payload_hash text NOT NULL,occurred_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),projection_state text NOT NULL CHECK(projection_state IN('applied','stale','quarantined')),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,provider_event_id));
CREATE TABLE budget_policies(workspace_id uuid NOT NULL,id uuid NOT NULL,name text NOT NULL,currency text NOT NULL,amount numeric(24,6) NOT NULL,mode text NOT NULL CHECK(mode IN('soft','hard')),period text NOT NULL CHECK(period IN('monthly','quarterly','annual')),scope jsonb NOT NULL DEFAULT '{}'::jsonb,state text NOT NULL DEFAULT 'active',revision integer NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,id));
CREATE TABLE budget_thresholds(workspace_id uuid NOT NULL,id uuid NOT NULL,budget_id uuid NOT NULL,percent numeric(6,3) NOT NULL CHECK(percent>0 AND percent<=100),action text NOT NULL CHECK(action IN('notify','stop')),channels jsonb NOT NULL,state text NOT NULL DEFAULT 'active',revision integer NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,budget_id) REFERENCES budget_policies(workspace_id,id));
CREATE TABLE usage_ledger(workspace_id uuid NOT NULL,id uuid NOT NULL,entry_kind text NOT NULL CHECK(entry_kind IN('RESERVE','INCREMENT','FINALIZE','RELEASE','ADJUST')),meter text NOT NULL,quantity numeric(38,12) NOT NULL,unit text NOT NULL,original_amount numeric(38,12) NOT NULL,currency text NOT NULL,price_version text NOT NULL,fx_version text,source_type text NOT NULL,source_id text NOT NULL,idempotency_key text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,idempotency_key));
CREATE INDEX usage_ledger_meter_idx ON usage_ledger(workspace_id,meter,occurred_at);
CREATE TABLE billing_invoices(workspace_id uuid NOT NULL,id uuid NOT NULL,provider_invoice_ref text,total numeric(24,6) NOT NULL,currency text NOT NULL,state text NOT NULL,due_at timestamptz,hosted_url text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['billing_plan_versions','billing_subscriptions','billing_webhook_receipts','budget_policies','budget_thresholds','usage_ledger','billing_invoices'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I_tenant ON %I USING (knotline_tenant_visible(workspace_id)) WITH CHECK (knotline_tenant_visible(workspace_id))',table_name,table_name);END LOOP;END $$;
REVOKE ALL ON billing_plan_versions,billing_subscriptions,billing_webhook_receipts,budget_policies,budget_thresholds,usage_ledger,billing_invoices FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE,DELETE ON billing_plan_versions,billing_subscriptions,billing_webhook_receipts,budget_policies,budget_thresholds,billing_invoices TO knotline_runtime;
GRANT SELECT,INSERT ON usage_ledger TO knotline_runtime;
GRANT SELECT ON billing_plan_versions,billing_subscriptions,budget_policies,budget_thresholds,usage_ledger,billing_invoices TO knotline_reporting;
